<script setup lang="ts">import{inject,ref,onMounted,computed}from'vue';import type Keycloak from'keycloak-js';import{catalog,offers,orders,errorMessage}from'./api';const kc=inject<Keycloak>('keycloak')!;const rows=ref<any[]>([]),manufacturers=ref<any[]>([]),total=ref(0),loading=ref(false),error=ref(''),q=ref(''),brand=ref(''),fuel=ref(''),offset=ref(0),selected=ref<any|null>(null),quote=ref<any|null>(null),quoteError=ref(''),quoteBusy=ref(false),createdOffer=ref<any|null>(null),offerActionBusy=ref(false),offerActionError=ref(''),showOffers=ref(false),offerRows=ref<any[]>([]),offerTotal=ref(0),offerLoading=ref(false),offerListError=ref(''),offerStatus=ref(''),offerSearch=ref(''),offerOffset=ref(0),expandedOfferId=ref(''),offerHistory=ref<Record<string,any[]>>({}),offerHistoryLoading=ref(''),offerHistoryError=ref(''),offerOrderBusy=ref(false),offerOrderError=ref('');const form=ref({vehiclePrice:'',downPayment:'0.00',residualValue:'0.00',currency:'EUR',durationMonths:36,annualInterestRateBasisPoints:500});const pages=computed(()=>Math.max(1,Math.ceil(total.value/12)));async function loadOffers(){offerLoading.value=true;offerListError.value='';try{const r=await offers.list({limit:10,offset:offerOffset.value,status:offerStatus.value||undefined,search:offerSearch.value.trim()||undefined});offerRows.value=r.data.items;offerTotal.value=r.data.total}catch(e){offerListError.value=errorMessage(e)}finally{offerLoading.value=false}}function openOffers(){selected.value=null;showOffers.value=true;offerOffset.value=0;void loadOffers()}async function createOrderFromOffer(offer:any){offerOrderError.value='';if(offer.status!=='accepted'){offerOrderError.value='Nur angenommene Angebote können in einen Auftrag übernommen werden.';return}if(!offer.offerId||!offer.quoteId||!offer.vehicleId){offerOrderError.value='Offer, Quote oder Vehicle Referenz fehlt im API-Ergebnis.';return}offerOrderBusy.value=true;try{const key='autoflow-order-'+Date.now()+'-'+Math.random().toString(16).slice(2);await orders.create({offerId:offer.offerId,quoteId:offer.quoteId,vehicleId:offer.vehicleId},key);window.location.assign('/operations.html')}catch(e){offerOrderError.value=errorMessage(e)}finally{offerOrderBusy.value=false}}function openVehicles(){showOffers.value=false;selected.value=null}function statusLabel(s:string){return({draft:'Entwurf',published:'Veröffentlicht',accepted:'Angenommen',rejected:'Abgelehnt',expired:'Abgelaufen',withdrawn:'Zurückgezogen'} as Record<string,string>)[s]||label(s)}function formatDate(s:string){return s?new Date(s).toLocaleString('de-DE'):'–'}async function updateListedOffer(id:string,action:'publish'|'accept'|'reject'){offerActionBusy.value=true;offerListError.value='';try{await offers[action](id);delete offerHistory.value[id];await loadOffers();if(expandedOfferId.value===id){expandedOfferId.value='';await toggleOfferDetails(id)}}catch(e){offerListError.value=errorMessage(e)}finally{offerActionBusy.value=false}}async function toggleOfferDetails(id:string){if(expandedOfferId.value===id){expandedOfferId.value='';return}expandedOfferId.value=id;offerHistoryError.value='';if(offerHistory.value[id])return;offerHistoryLoading.value=id;try{const r=await offers.history(id);offerHistory.value[id]=r.data.items}catch(e){offerHistoryError.value=errorMessage(e)}finally{offerHistoryLoading.value=''}}async function downloadOfferPdf(id:string){offerActionBusy.value=true;offerListError.value='';try{const response=await offers.downloadPdf(id);const url=URL.createObjectURL(response.data);const link=document.createElement('a');link.href=url;link.download='autoflow-offer-'+id+'.pdf';document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url)}catch(e){offerListError.value=errorMessage(e)}finally{offerActionBusy.value=false}}function historyLabel(eventType:string){return({'offer.created':'Angebot erstellt','offer.published':'Angebot veröffentlicht','offer.accepted':'Angebot angenommen','offer.rejected':'Angebot abgelehnt','offer.expired':'Angebot abgelaufen','offer.withdrawn':'Angebot zurückgezogen'} as Record<string,string>)[eventType]||label(eventType)}function nextOffersPage(direction:number){offerOffset.value=Math.max(0,offerOffset.value+direction*10);void loadOffers()}async function load(){loading.value=true;error.value='';try{const r=await catalog.list({limit:12,offset:offset.value,q:q.value||undefined,manufacturerId:brand.value||undefined,fuelType:fuel.value||undefined});rows.value=r.data.items;total.value=r.data.total}catch(e){error.value=errorMessage(e)}finally{loading.value=false}}async function detail(v:any){try{selected.value=(await catalog.detail(v.variantId)).data;quote.value=null;quoteError.value='';createdOffer.value=null;offerActionError.value=''}catch(e){error.value=errorMessage(e)}}function pricingPayload(){return{...form.value,vehiclePrice:Number(form.value.vehiclePrice).toFixed(2),downPayment:Number(form.value.downPayment).toFixed(2),residualValue:Number(form.value.residualValue).toFixed(2)}}async function createOffer(){if(!selected.value)return;offerActionBusy.value=true;offerActionError.value='';try{createdOffer.value=(await offers.create(selected.value.variantId,pricingPayload())).data;quote.value=createdOffer.value.pricing}catch(e){offerActionError.value=errorMessage(e)}finally{offerActionBusy.value=false}}async function changeOfferStatus(action:'publish'|'accept'|'reject'){if(!createdOffer.value)return;offerActionBusy.value=true;offerActionError.value='';try{createdOffer.value=(await offers[action](createdOffer.value.offerId)).data}catch(e){offerActionError.value=errorMessage(e)}finally{offerActionBusy.value=false}}async function refreshOffer(){if(!createdOffer.value)return;offerActionBusy.value=true;offerActionError.value='';try{createdOffer.value=(await offers.show(createdOffer.value.offerId)).data}catch(e){offerActionError.value=errorMessage(e)}finally{offerActionBusy.value=false}}async function calculate(){if(!selected.value||Number(form.value.vehiclePrice)<=0||Number(form.value.downPayment)<0||Number(form.value.residualValue)<0){quoteError.value='Bitte Fahrzeugpreis und Restwert angeben.';return}quoteBusy.value=true;quoteError.value='';try{quote.value=(await offers.quote(selected.value.variantId,pricingPayload())).data}catch(e){quoteError.value=errorMessage(e)}finally{quoteBusy.value=false}}function money(v:string|number,c='EUR'){return Number(v).toLocaleString('de-DE',{style:'currency',currency:c})}function label(s:string){return(s||'').replaceAll('_',' ')}onMounted(async()=>{await load();try{manufacturers.value=(await catalog.manufacturers()).data.items}catch(e){console.warn(e)}});</script>
<template><div class="shell"><header><a class="logo" @click="openVehicles">A<span>AUTOFLOW<small>MOBILITY PLATFORM</small></span></a><nav><a @click="openVehicles">Fahrzeuge</a><a @click="openOffers">Meine Angebote</a><a href="/operations.html">Aufträge & Payments</a><a href="http://localhost:8081/api/doc" target="_blank">Offer API ↗</a></nav><div class="account"><i></i>{{kc.tokenParsed?.preferred_username}}<button @click="kc.logout()">Abmelden</button></div></header><main><template v-if="showOffers"><button class="back" @click="openVehicles">← Fahrzeugkatalog</button><section class="heading"><div><p class="eyebrow">OFFER MANAGEMENT</p><h1>Meine <em>Angebote.</em></h1><p>Alle Angebote deines Kontos im aktuellen Mandanten.</p></div><strong>{{offerTotal}}<small>gespeicherte Angebote</small></strong></section><section class="filters"><input v-model="offerSearch" @keyup.enter="offerOffset=0;loadOffers()" placeholder="Angebots-ID, Quote oder Fahrzeug suchen …"/><select v-model="offerStatus" @change="offerOffset=0;loadOffers()"><option value="">Alle Status</option><option value="draft">Entwurf</option><option value="published">Veröffentlicht</option><option value="accepted">Angenommen</option><option value="rejected">Abgelehnt</option><option value="expired">Abgelaufen</option><option value="withdrawn">Zurückgezogen</option></select><button class="primary" type="button" @click="offerOffset=0;loadOffers()">Suchen ↗</button></section><div v-if="offerListError" class="error">{{offerListError}} <button @click="loadOffers">Erneut versuchen</button></div><div v-else-if="offerLoading" class="empty">Angebote werden geladen …</div><div v-else-if="!offerRows.length" class="empty">Keine Angebote für diese Suche gefunden.</div><div v-else-if="offerOrderError" class="error">{{offerOrderError}}</div><section v-else class="offers-grid"><article v-for="offer in offerRows" :key="offer.offerId" class="offer-card"><div class="offer-card-top"><span class="eyebrow">AUTOFLOW OFFER</span><span class="status-pill" :class="'status-'+offer.status">{{statusLabel(offer.status)}}</span></div><h2>{{offer.vehicleId}}</h2><p class="offer-id">{{offer.offerId}}</p><div class="offer-data"><div><small>Monatliche Rate</small><b>{{money(offer.pricing.monthlyAmount,offer.pricing.currency)}}</b></div><div><small>Laufzeit</small><b>{{offer.pricing.durationMonths}} Monate</b></div><div><small>Erstellt</small><b>{{formatDate(offer.createdAt)}}</b></div><div><small>Gültig bis</small><b>{{formatDate(offer.expiresAt)}}</b></div></div><div class="offer-lifecycle-actions"><button v-if="offer.status==='draft'" :disabled="offerActionBusy" @click="updateListedOffer(offer.offerId,'publish')">Veröffentlichen</button><button v-if="offer.status==='published'" :disabled="offerActionBusy" @click="updateListedOffer(offer.offerId,'accept')">Annehmen</button><button v-if="offer.status==='published'" :disabled="offerActionBusy" @click="updateListedOffer(offer.offerId,'reject')">Ablehnen</button></div><div class="offer-card-actions"><button @click="toggleOfferDetails(offer.offerId)">{{expandedOfferId===offer.offerId?'Details schließen':'Details & Verlauf anzeigen ↗'}}</button><button v-if="offer.status==='accepted'" :disabled="offerOrderBusy" @click.stop="createOrderFromOffer(offer)">{{offerOrderBusy?'Auftrag wird erstellt …':'Auftrag erstellen ↗'}}</button><button :disabled="offerActionBusy" @click="downloadOfferPdf(offer.offerId)">PDF herunterladen ↓</button></div><div v-if="expandedOfferId===offer.offerId" class="offer-expanded"><div class="offer-data"><div><small>Quote ID</small><b>{{offer.quoteId}}</b></div><div><small>Gesamtkosten</small><b>{{money(offer.pricing.totalCostIncludingDownPayment,offer.pricing.currency)}}</b></div><div><small>Anzahlung</small><b>{{money(offer.pricing.totalCostIncludingDownPayment-offer.pricing.totalInstallmentsAmount,offer.pricing.currency)}}</b></div><div><small>Restwert</small><b>{{money(offer.pricing.residualValue,offer.pricing.currency)}}</b></div></div><div class="offer-timeline"><p v-if="offerHistoryLoading===offer.offerId">Verlauf wird geladen …</p><p v-else-if="offerHistoryError" class="error">{{offerHistoryError}}</p><p v-else-if="!offerHistory[offer.offerId]?.length">Noch keine Audit-Ereignisse vorhanden.</p><p v-for="event in offerHistory[offer.offerId]" :key="event.eventId"><span class="timeline-dot"></span><b>{{historyLabel(event.eventType)}}</b><time>{{formatDate(event.occurredAt)}}</time><small>{{event.fromStatus?statusLabel(event.fromStatus)+' → ':''}}{{statusLabel(event.toStatus)}} · {{event.actorType==='system'?'System':'Benutzer'}}</small></p></div></div></article></section><div class="pagination" v-if="offerTotal>10"><button :disabled="offerOffset===0" @click="nextOffersPage(-1)">← Zurück</button>{{Math.floor(offerOffset/10)+1}} / {{Math.ceil(offerTotal/10)}}<button :disabled="offerOffset+10>=offerTotal" @click="nextOffersPage(1)">Weiter →</button></div></template><template v-else><template v-if="!selected"><section class="heading"><div><p class="eyebrow">DISCOVER YOUR NEXT DRIVE</p><h1>Fahrzeuge <em>im Überblick.</em></h1><p>Entdecke den AutoFlow Fahrzeugkatalog und finde dein passendes Modell.</p></div><strong>{{total}}<small>publizierte Varianten</small></strong></section><section class="filters"><input v-model="q" @input="offset=0;load()" placeholder="Marke, Modell oder Variante suchen …"/><select v-model="brand" @change="offset=0;load()"><option value="">Alle Hersteller</option><option v-for="m in manufacturers" :value="m.manufacturerId">{{m.name}}</option></select><select v-model="fuel" @change="offset=0;load()"><option value="">Alle Kraftstoffe</option><option value="petrol">Benzin</option><option value="diesel">Diesel</option><option value="electric">Elektro</option><option value="hybrid">Hybrid</option><option value="plug_in_hybrid">Plug-in-Hybrid</option></select></section><div class="result">{{total}} ERGEBNISSE <span>SEITE {{Math.floor(offset/12)+1}} / {{pages}}</span></div><div v-if="error" class="error">{{error}} <button @click="load">Erneut versuchen</button></div><div v-else-if="loading" class="empty">Fahrzeuge werden geladen …</div><div v-else-if="!rows.length" class="empty">Keine veröffentlichten Fahrzeuge gefunden.</div><section v-else class="grid"><article v-for="v in rows" :key="v.variantId" @click="detail(v)"><div class="visual"><span>{{v.manufacturer.code}}</span><b>↗</b><small>{{label(v.bodyStyle)}}</small></div><div class="card"><label>{{v.manufacturer.name}} · {{v.model.name}}</label><h2>{{v.name}}</h2><p>{{v.generation.name}}</p><div class="spec"><span>{{v.powerKw?v.powerKw+' kW':'Leistung n. a.'}}</span><span>{{label(v.fuelType)}}</span><span>{{label(v.transmission)}}</span></div><footer>Preis auf Anfrage <b>↗</b></footer></div></article></section><div class="pagination"><button :disabled="offset===0" @click="offset=Math.max(0,offset-12);load()">← Zurück</button>{{Math.floor(offset/12)+1}} / {{pages}}<button :disabled="offset+12>=total" @click="offset+=12;load()">Weiter →</button></div><p class="note">Live-Daten aus dem Vehicle Catalog Service · Preise sind nicht Bestandteil des Katalogs.</p></template><template v-else><button class="back" @click="selected=null;quote=null">← Fahrzeugkatalog</button><section class="hero"><div><p class="eyebrow">{{selected.manufacturer.name}} / {{selected.model.name}}</p><h1>{{selected.name}}</h1><p>{{selected.generation.name}} · {{label(selected.bodyStyle)}}</p></div><div class="hero-art">AF / {{selected.manufacturer.code}}</div></section><section class="detail"><div class="panel"><p class="eyebrow">TECHNICAL OVERVIEW</p><h2>Fahrzeugdaten</h2><div class="specgrid"><div><small>Hersteller</small><b>{{selected.manufacturer.name}}</b></div><div><small>Modell</small><b>{{selected.model.name}}</b></div><div><small>Generation</small><b>{{selected.generation.name}}</b></div><div><small>Leistung</small><b>{{selected.powerKw?selected.powerKw+' kW':'–'}}</b></div><div><small>Kraftstoff</small><b>{{label(selected.fuelType)}}</b></div><div><small>Getriebe</small><b>{{label(selected.transmission)}}</b></div><div><small>Sitzplätze</small><b>{{selected.seats??'–'}}</b></div><div><small>Gewicht</small><b>{{selected.curbWeightKg?selected.curbWeightKg+' kg':'–'}}</b></div><div><small>CO₂</small><b>{{selected.co2EmissionGPerKm?selected.co2EmissionGPerKm+' g/km':'–'}}</b></div></div></div><aside class="panel quote"><p class="eyebrow">OFFER / PRICING</p><h2>Leasing kalkulieren.</h2><p>Der Katalog besitzt keine Preise. Gib die Kalkulationswerte ein; Offer leitet die Anfrage an Pricing weiter.</p><form @submit.prevent="calculate"><label>Fahrzeugpreis (EUR)<input v-model="form.vehiclePrice" type="number" min=".01" step=".01" required placeholder="z. B. 30000.00"/></label><label>Anzahlung (EUR)<input v-model="form.downPayment" type="number" min="0" step=".01" required/></label><label>Restwert (EUR)<input v-model="form.residualValue" type="number" min="0" step=".01" required/></label><div class="pair"><label>Laufzeit<select v-model.number="form.durationMonths"><option :value="24">24 Monate</option><option :value="36">36 Monate</option><option :value="48">48 Monate</option><option :value="60">60 Monate</option></select></label><label>Zins p.a. (%)<input type="number" min="0" step=".01" :value="form.annualInterestRateBasisPoints/100" @input="form.annualInterestRateBasisPoints=Math.round(Number(($event.target as HTMLInputElement).value)*100)"/></label></div><div class="action-stack"><button class="primary" :disabled="quoteBusy" type="submit">{{quoteBusy?'Berechnung läuft …':'Nur Rate berechnen ↗'}}</button><button class="primary secondary" type="button" :disabled="offerActionBusy" @click="createOffer">{{offerActionBusy?'Angebot wird erstellt …':'Echtes Angebot erstellen ↗'}}</button></div></form><p v-if="quoteError" class="error">{{quoteError}}</p><div v-if="quote" class="quote-result"><small>MONATLICHE RATE</small><strong>{{money(quote.monthlyAmount,quote.currency)}}</strong><p>Gesamtkosten inkl. Anzahlung <b>{{money(quote.totalCostIncludingDownPayment,quote.currency)}}</b></p></div><div v-if="createdOffer" class="created-offer"><p class="eyebrow">OFFER ERFOLGREICH ANGELEGT</p><div class="offer-id">{{createdOffer.offerId}}</div><div class="offer-meta"><span>Status</span><b>{{label(createdOffer.status)}}</b></div><div class="offer-meta"><span>Angebots-ID</span><b>{{createdOffer.offerId}}</b></div><div class="offer-meta"><span>Gültig bis</span><b>{{createdOffer.expiresAt||'–'}}</b></div><div class="offer-actions"><button type="button" @click="refreshOffer" :disabled="offerActionBusy">Aktualisieren</button><button type="button" v-if="createdOffer.status==='draft'" @click="changeOfferStatus('publish')" :disabled="offerActionBusy">Veröffentlichen</button><button type="button" v-if="createdOffer.status==='published'" @click="changeOfferStatus('accept')" :disabled="offerActionBusy">Annehmen</button><button type="button" v-if="createdOffer.status==='published'" @click="changeOfferStatus('reject')" :disabled="offerActionBusy">Ablehnen</button></div></div><p v-if="offerActionError" class="error">{{offerActionError}}</p></aside></section></template></template></main><div class="bottom">AUTOFLOW MOBILITY <span>VEHICLE CATALOG · OFFER · PRICING</span></div></div></template>